#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int N = 1000000;
const ll MOD = 1000000007LL;

ll factorial[N + 1], inverseFactorial[N + 1];

ll modPow(ll a, ll b) {
    ll result = 1;
    while (b > 0) {
        if (b & 1) result = result * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return result;
}

bool isGood(ll sum, int a, int b) {
    while (sum > 0) {
        int digit = sum % 10;
        if (digit != a && digit != b) return false;
        sum /= 10;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, n;
    cin >> a >> b >> n;

    factorial[0] = 1;
    for (int i = 1; i <= n; ++i)
        factorial[i] = factorial[i - 1] * i % MOD;

    inverseFactorial[n] = modPow(factorial[n], MOD - 2);
    for (int i = n; i > 0; --i)
        inverseFactorial[i - 1] = inverseFactorial[i] * i % MOD;

    ll answer = 0;

    for (int i = 0; i <= n; ++i) {
        ll sum = 1LL * i * a + 1LL * (n - i) * b;

        if (isGood(sum, a, b)) {
            ll combinations = factorial[n] * inverseFactorial[i] % MOD;
            combinations = combinations * inverseFactorial[n - i] % MOD;
            answer = (answer + combinations) % MOD;
        }
    }

    cout << answer << '\n';
    return 0;
}

